```csharp
using System;
using System.Linq;
using Microsoft.EntityFrameworkCore;

namespace RV.InvNew.Common
{
    public static class DiscountCalculator
    {
        /// <summary>
        /// Calculate the effective discount for an item based on various discount rules
        /// </summary>
        /// <param name="inventoryQuery">Queryable inventory record</param>
        /// <param name="catalogueQuery">Queryable catalogue record</param>
        /// <param name="piiQuery">Queryable PII record for customer discounts</param>
        /// <param name="volumeDiscountsQuery">Queryable volume discounts</param>
        /// <param name="quantity">Quantity being purchased</param>
        /// <param name="useMaxDiscountMethod">Whether to use maximum discount (true) or combine discounts (false)</param>
        /// <returns>Tuple of (discount percentage, explanation)</returns>
        public static (IQueryable<(double DiscountPercentage, string Explanation)>, string) CalculateDiscount(
            IQueryable<Inventory> inventoryQuery,
            IQueryable<Catalogue> catalogueQuery,
            IQueryable<Pii> piiQuery,
            IQueryable<VolumeDiscount> volumeDiscountsQuery,
            double quantity)
        {
            // Start with an empty query that we'll build up
            var queryBuilder = new[] { (DiscountPercentage: 0.0, Explanation: "Starting discount calculation") }.AsQueryable().Track();

            // Base discounts from inventory record
            queryBuilder = queryBuilder.ApplyRule(
                "Get base multiplicative and additive discounts from inventory",
                q => q.Join(inventoryQuery, 
                    d => true, // Join with all inventory records (will be filtered later)
                    i => true,
                    (d, i) => new 
                    { 
                        Inventory = i,
                        BaseDiscount = d.DiscountPercentage
                    })
                .Join(catalogueQuery,
                    x => x.Inventory.Itemcode,
                    c => c.Itemcode,
                    (x, c) => new 
                    { 
                        Inventory = x.Inventory,
                        Catalogue = c,
                        BaseDiscount = x.BaseDiscount
                    })
                .Select(x => new 
                    { 
                        // Calculate base discount from inventory
                        // Apply multiplicative discount first, then additive
                        BaseDiscount = x.BaseDiscount + (x.Inventory.MultiplicativeDiscountPercentage * (100 - x.BaseDiscount) / 100),
                        Inventory = x.Inventory,
                        Catalogue = x.Catalogue
                    })
                .Select(x => new
                    {
                        DiscountPercentage = x.BaseDiscount,
                        Explanation = $"Base discount: {x.Inventory.MultiplicativeDiscountPercentage:F2}% multiplicative + {x.Inventory.AdditiveDiscountPercentage:F2}% additive = {x.BaseDiscount:F2}%",
                        Inventory = x.Inventory,
                        Catalogue = x.Catalogue
                    })
            );

            // Add customer-specific discounts if applicable
            queryBuilder = queryBuilder.ApplyRule(
                "Add customer-specific discounts if applicable",
                q => q.GroupJoin(piiQuery,
                    x => true, // Will be filtered by actual customer ID in actual implementation
                    p => true,
                    (x, pGroup) => new { x, PiiGroup = pGroup })
                .SelectMany(
                    x => x.PiiGroup.DefaultIfEmpty(),
                    (x, p) => new 
                    { 
                        DiscountPercentage = x.x.DiscountPercentage,
                        Explanation = x.x.Explanation,
                        Inventory = x.x.Inventory,
                        Catalogue = x.x.Catalogue,
                        CustomerDiscount = p != null ? 
                            // Calculate customer discount
                            (p.DiscountRateMultiplicativePercentage * (100 - x.x.DiscountPercentage) / 100) + p.DiscountRateAdditivePercentage 
                            : 0
                    })
                .Select(x => new
                    {
                        // Apply customer discount if applicable
                        DiscountPercentage = x.DiscountPercentage + x.CustomerDiscount,
                        Explanation = x.CustomerDiscount > 0 ? 
                            $"{x.Explanation}\nCustomer discount: {x.CustomerDiscount:F2}%" : 
                            x.Explanation,
                        Inventory = x.Inventory,
                        Catalogue = x.Catalogue
                    })
            );

            // Add volume discounts if applicable
            queryBuilder = queryBuilder.ApplyRule(
                "Add volume discounts if applicable",
                q => q.GroupJoin(volumeDiscountsQuery,
                    x => x.Inventory.Itemcode,
                    v => v.Itemcode,
                    (x, vGroup) => new { x, VolumeDiscounts = vGroup })
                .SelectMany(
                    x => x.VolumeDiscounts.DefaultIfEmpty(),
                    (x, v) => new 
                    { 
                        DiscountPercentage = x.x.DiscountPercentage,
                        Explanation = x.x.Explanation,
                        Inventory = x.x.Inventory,
                        Catalogue = x.x.Catalogue,
                        VolumeDiscount = v != null && v.StartFrom <= quantity ? v.DiscountPerUnit : 0
                    })
                .Select(x => new
                    {
                        // Apply volume discount if applicable
                        DiscountPercentage = x.DiscountPercentage + x.VolumeDiscount,
                        Explanation = x.VolumeDiscount > 0 ? 
                            $"{x.Explanation}\nVolume discount (qty {quantity}): {x.VolumeDiscount:F2}%" : 
                            x.Explanation,
                        Inventory = x.Inventory,
                        Catalogue = x.Catalogue
                    })
            );

            // Apply final discount logic based on catalogue settings
            queryBuilder = queryBuilder.ApplyRule(
                "Apply final discount logic based on catalogue settings",
                q => q.Select(x => new
                    {
                        // Check if we should use maximum discount or combine all
                        DiscountPercentage = x.Catalogue.DiscountMethodIsMaximum ? 
                            Math.Max(x.DiscountPercentage, Math.Max(
                                x.Inventory.MultiplicativeDiscountPercentage, 
                                x.Inventory.AdditiveDiscountPercentage)) :
                            x.DiscountPercentage,
                        Explanation = x.Catalogue.DiscountMethodIsMaximum ? 
                            $"{x.Explanation}\nUsing maximum discount method" : 
                            x.Explanation,
                        Inventory = x.Inventory,
                        Catalogue = x.Catalogue
                    })
                .Select(x => new
                    {
                        // Ensure discount doesn't make price below minimum
                        DiscountPercentage = Math.Min(x.DiscountPercentage, 
                            ((x.Inventory.SellingPrice - x.Inventory.MinPrice) / x.Inventory.SellingPrice) * 100),
                        Explanation = x.DiscountPercentage > ((x.Inventory.SellingPrice - x.Inventory.MinPrice) / x.Inventory.SellingPrice) * 100 ? 
                            $"{x.Explanation}\nDiscount capped to maintain minimum price" : 
                            x.Explanation,
                        Inventory = x.Inventory,
                        Catalogue = x.Catalogue
                    })
                .Select(x => (DiscountPercentage: x.DiscountPercentage, Explanation: x.Explanation))
            );

            return queryBuilder.Finalize();
        }
    }

    public static class LoyaltyPointsCalculator
    {
        /// <summary>
        /// Calculate loyalty points for a sale
        /// </summary>
        /// <param name="salePrice">Total sale price after discounts</param>
        /// <param name="piiQuery">Queryable PII record for customer</param>
        /// <param name="defaultCashAccountQuery">Queryable default cash account for loyalty calculation</param>
        /// <returns>Tuple of (loyalty points percentage, explanation)</returns>
        public static (IQueryable<(double PointsPercentage, string Explanation)>, string) CalculateLoyaltyPoints(
            double salePrice,
            IQueryable<Pii> piiQuery,
            IQueryable<AccountsInformation> defaultCashAccountQuery)
        {
            // Start with an empty query that we'll build up
            var queryBuilder = new[] { (PointsPercentage: 0.0, Explanation: "Starting loyalty points calculation") }.AsQueryable().Track();

            // Get base loyalty points rate from customer or default cash account
            queryBuilder = queryBuilder.ApplyRule(
                "Get base loyalty points rate from customer or default cash account",
                q => q.GroupJoin(piiQuery,
                    x => true, // Will be filtered by actual customer ID in actual implementation
                    p => true,
                    (x, pGroup) => new { x, PiiGroup = pGroup })
                .SelectMany(
                    x => x.PiiGroup.DefaultIfEmpty(),
                    (x, p) => new 
                    { 
                        BasePointsPercentage = p != null ? 
                            // Calculate customer loyalty points rate
                            (p.LoyaltyPointsRateMultiplicativePercentage * (100 - x.x.PointsPercentage) / 100) + p.LoyaltyPointsRateAdditivePercentage :
                            // Use default cash account if no customer-specific rate
                            defaultCashAccountQuery.Select(a => a.LoyaltyBaseMultiplicativePointsPercentage).FirstOrDefault(),
                        Explanation = x.x.Explanation,
                        HasCustomerRate = p != null
                    })
                .Select(x => new
                    {
                        PointsPercentage = x.BasePointsPercentage,
                        Explanation = x.HasCustomerRate ? 
                            $"{x.Explanation}\nCustomer loyalty rate: {x.BasePointsPercentage:F2}%" : 
                            $"{x.Explanation}\nDefault cash account loyalty rate: {x.BasePointsPercentage:F2}%"
                    })
            );

            return queryBuilder.Finalize();
        }
    }

