    public static class SaleProcessor
    {
        /// <summary>
        /// Process a sale with all calculations
        /// </summary>
        /// <param name="dbContext">Database context</param>
        /// <param name="saleDTO">Sale data transfer object</param>
        /// <param name="customerId">Customer ID for loyalty points</param>
        /// <returns>Processed sale with all calculated values</returns>
        public static IQueryable<Sale> ProcessSale(
            IQueryable<Inventory> inventoryQuery,
            IQueryable<Catalogue> catalogueQuery,
            IQueryable<Pii> piiQuery,
            IQueryable<VolumeDiscount> volumeDiscountsQuery,
            IQueryable<AccountsInformation> defaultCashAccountQuery,
            SaleDTO saleDTO,
            long? customerId = null)
        {
            // Get the inventory and catalogue records for this item
            var itemQuery = inventoryQuery.Where(i => i.Itemcode == saleDTO.Itemcode && i.Batchcode == saleDTO.Batchcode)
                .Join(catalogueQuery,
                    i => i.Itemcode,
                    c => c.Itemcode,
                    (i, c) => new { Inventory = i, Catalogue = c });

            // Calculate discount
            var (discountQuery, discountExplanation) = DiscountCalculator.CalculateDiscount(
                inventoryQuery.Where(i => i.Itemcode == saleDTO.Itemcode && i.Batchcode == saleDTO.Batchcode),
                catalogueQuery.Where(c => c.Itemcode == saleDTO.Itemcode),
                customerId.HasValue ? piiQuery.Where(p => p.Id == customerId.Value) : new List<Pii>().AsQueryable(),
                volumeDiscountsQuery.Where(v => v.Itemcode == saleDTO.Itemcode),
                saleDTO.Quantity);

            // Calculate loyalty points
            var (loyaltyQuery, loyaltyExplanation) = LoyaltyPointsCalculator.CalculateLoyaltyPoints(
                saleDTO.SellingPrice * saleDTO.Quantity, // Total price before discount
                customerId.HasValue ? piiQuery.Where(p => p.Id == customerId.Value) : new List<Pii>().AsQueryable(),
                defaultCashAccountQuery.Where(a => a.IsDefaultCashRegister));

            // Apply calculations to the sale
            return itemQuery
                .Join(discountQuery,
                    i => true,
                    d => true,
                    (i, d) => new { i.Inventory, i.Catalogue, Discount = d.DiscountPercentage, DiscountExplanation = d.Explanation })
                .Join(loyaltyQuery,
                    x => true,
                    l => true,
                    (x, l) => new { x.Inventory, x.Catalogue, x.Discount, x.DiscountExplanation, LoyaltyPercentage = l.PointsPercentage, LoyaltyExplanation = l.Explanation })
                .Select(x => new Sale
                {
                    Itemcode = x.Inventory.Itemcode,
                    Batchcode = x.Inventory.Batchcode,
                    Quantity = saleDTO.Quantity,
                    SellingPrice = x.Inventory.SellingPrice,
                    VatCategory = x.Catalogue.DefaultVatCategory,
                    VatRatePercentage = 20.0, // This would come from VAT table in real implementation
                    DiscountRate = x.Discount,
                    Discount = x.Inventory.SellingPrice * x.Discount / 100 * saleDTO.Quantity,
                    VatAsCharged = x.Inventory.SellingPrice * (100 - x.Discount) / 100 * saleDTO.Quantity * 0.2, // Simplified VAT calculation
                    TotalEffectiveSellingPrice = x.Inventory.SellingPrice * (100 - x.Discount) / 100 * saleDTO.Quantity * 1.2, // Price with VAT
                    Remarks = $"{x.DiscountExplanation}\n{x.LoyaltyExplanation}",
                    ClientRecordedTimeOpening = DateTime.Now,
                    ClientRecordedTimeClosing = DateTime.Now,
                    LoyalityPointsPercentage = x.LoyaltyPercentage,
                    LoyalityPointsIssued = x.Inventory.SellingPrice * (100 - x.Discount) / 100 * saleDTO.Quantity * x.LoyaltyPercentage / 100,
                    ProductName = x.Catalogue.Description
                });
        }
    }
}
